import org.springframework.stereotype.Service
import org.springframework.beans.factory.annotation.Value

@Service
class AService {
    @Value("\${batchService.http.url}")
    var url: String = ""

    fun setUrlBad(urlParam: String) {
        url = urlParam // bad - unguarded
        this.url = urlParam // bad - unguarded with this
    }
}

import org.springframework.stereotype.Component
import org.springframework.beans.factory.annotation.Autowired
import net.jcip.annotations.GuardedBy
import kotlin.jvm.Synchronized
import kotlin.jvm.Volatile

@Component
class ProtectedFields {
    @Volatile
    var volatileField: String = ""

    @GuardedBy("lock")
    var guardedField: String = ""

    var injectedField: String = ""

    @Synchronized
    fun setVolatileGood(v: String) {
        volatileField = v // good: @Synchronized function
    }

    @Autowired
    fun setInjected(dep: String) {
        injectedField = dep // good: @Autowired function
    }
}

import org.springframework.stereotype.Component
