import org.springframework.stereotype.Component
import javax.annotation.PostConstruct

@Component
class WithCompanionAndInit {
    var initField: String = ""
    var postField: String = ""

    fun afterPropertiesSet() {
        initField = "initialized" // good - afterPropertiesSet
    }

    @PostConstruct
    fun init() {
        postField = "post" // good - @PostConstruct
    }

    companion object {
        var staticField: String = "" // companion object - not flagged
    }
}

