import org.springframework.stereotype.Component
import kotlin.jvm.Volatile

@Component
class Foo {
    var url: String = ""
    var boringField: String = ""
    @Volatile var volatileGood: String = ""
    var wiredGood: String = ""

    fun setUrlBad(urlParam: String) {
        boringField = urlParam // bad - unguarded
        val urlx = urlParam + "x"
        urlParam.length // good, not assignment
        this.url = urlParam // bad - unguarded
    }

    fun setVolatileGood(vol: String) {
        volatileGood = vol // good - @Volatile field
    }
}

import org.springframework.stereotype.Component
