    var field: String = ""
    fun setField(f: String) {
        field = f // good - @ConfigurationProperties
    }
}

import org.springframework.stereotype.Service

@Service
class LocalVarShadowing {
    var url: String = ""

    fun doWork() {
        var url = "local"
        url = "reassigned" // good - local var shadows field
    }
}

import org.springframework.stereotype.Service

@Service
class ParamShadowing {
    var url: String = ""

    fun doWork(url: String) {
        val x = url // good, reading param
    }
}

import kotlin.jvm.Synchronized
import kotlin.jvm.Volatile
import org.springframework.stereotype.Service

@Service
class MyService {
    companion object {
        @Volatile var safeCounter: Int = 0       // guarded by @Volatile
        var unsafeCounter: Int = 0               // not guarded
    }
    fun incrementBad() {
        unsafeCounter = unsafeCounter + 1 // bad: unguarded assignment to companion var
    }
    @Synchronized
    fun incrementGood() {
        unsafeCounter = unsafeCounter + 1 // good: synchronized
    }
}

import org.springframework.context.annotation.Scope
import org.springframework.stereotype.Service
import org.springframework.web.bind.annotation.RequestMapping

@Service
@Scope("production")
@RequestMapping("request")
class ProductionScopedService {
    var mutableField: String = ""
    fun doWork() {
        mutableField = "x" // bad: shared mutable field, @Scope("production") is not request scope
    }
}
